#define MOD 1000000007LL

static long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    long long N, M;
    if (scanf("%lld %lld", &N, &M) != 2) return 0;

    /* 
       Key fact:
       A sequence is always sortable under the allowed adjacent swaps
       iff it is nondecreasing in Gray-code order for every projection
       obtained by zeroing arbitrary bit positions.

       This is possible exactly when all numbers in the sequence are equal.
       Reason:
       - If two adjacent distinct values remain after Snuke's operations,
         Takahashi may need to swap values whose Hamming distance > 1,
         which is impossible directly, and in general some projection breaks sortability.
       - Constant sequences are trivially sortable after any operations.

       Therefore the number of valid sequences is exactly the number of
       choices of that common value: 2^N.
    */

    printf("%lld\n", mod_pow(2, N));
    return 0;
}

