#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, M;
    cin >> N >> M;

    // Key observation:
    // After Snuke clears any subset of bit positions globally,
    // Takahashi must always be able to sort using adjacent swaps
    // where swapped values differ in exactly one bit.
    //
    // This is possible iff every adjacent pair in the original sequence
    // differs in exactly one bit.
    //
    // Reason:
    // - If adjacent values differ in one bit, then after clearing any bits,
    //   they differ in at most one bit, so any inversion can be fixed locally.
    // - If some adjacent pair differs in 0 or >=2 bits, choose Snuke's operation
    //   so that this pair remains an inversion but cannot be swapped, making sorting impossible.
    //
    // Therefore the valid sequences are exactly walks of length M on the N-dimensional hypercube:
    // - First element: any of 2^N values
    // - Each next element: choose one of N bits to flip
    //
    // Count = 2^N * N^(M-1), with the convention N^0 = 1.
    //
    // Special case N=0:
    // only value 0 exists, so only one sequence (all zeroes), which is valid.

    auto modpow = [&](long long a, long long e) {
        long long r = 1 % MOD;
        a %= MOD;
        while (e > 0) {
            if (e & 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    };

    long long ans = modpow(2, N) * modpow(N % MOD, M - 1) % MOD;
    cout << ans << '\n';
    return 0;
}

