import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int M = fs.nextInt();

        // If M == 1, any single element is always already sorted after any operation.
        if (M == 1) {
            System.out.println(modPow(1L << N, 1, MOD));
            return;
        }

        // Key observation:
        // For Takahashi to always be able to sort after any subset of bits is zeroed out,
        // the original sequence must be nondecreasing.
        //
        // Reason:
        // Adjacent swap is allowed only when two values differ in exactly one bit.
        // If the sequence after Snuke's operation is already nondecreasing, we're done.
        // Otherwise, to fix an inversion x > y, these two elements must cross at some point.
        // During any adjacent swap, the pair being swapped must differ in one bit, hence
        // their relative order can only be changed if such crossings are possible.
        //
        // Requiring this for every possible zeroing operation is extremely strong; in fact,
        // it implies the sequence must remain nondecreasing after zeroing any subset of bits.
        // This holds iff the original sequence is nondecreasing:
        // if a <= b, then (a & mask) <= (b & mask) for any mask of the form keeping some bits
        // and zeroing others? This is NOT true in general.
        //
        // So we need a stronger characterization.
        //
        // Let us define the condition for every adjacent pair (a_i, a_{i+1}):
        // after zeroing any subset of bits, we must have f(a_i) <= f(a_{i+1}),
        // otherwise an inversion can appear. But if an inversion appears for a pair,
        // they differ only by zeroed bits / kept bits; to guarantee sortable under all operations,
        // the pair must be swappable through the whole sequence structure. The exact global
        // characterization turns out to be:
        //
        // For every adjacent pair, the set of 1-bits of a_i must be a subset of the set of 1-bits
        // of a_{i+1}. Equivalently, a_i & ~a_{i+1} == 0.
        //
        // Because after applying any zeroing mask S (kept bits mask K), values become a_i & K.
        // Then to have (a_i & K) <= (a_{i+1} & K) for all K, it is necessary and sufficient that
        // every bit that is 1 in a_i is also 1 in a_{i+1}; otherwise keeping the highest differing
        // bit gives inversion.
        //
        // If all adjacent pairs satisfy subset relation, then the whole sequence is monotone
        // in bitwise subset order, hence after any zeroing operation it is still nondecreasing
        // numerically, so already sorted.
        //
        // Therefore we count sequences of length M:
        // x1 subseteq x2 subseteq ... subseteq xM
        // where each xi is an N-bit mask.
        //
        // Each bit evolves independently across the sequence as a binary nondecreasing sequence:
        // 0...0 1...1, determined by the first position where it becomes 1 (or never).
        // For one bit, number of such sequences of length M is M+1.
        // For N independent bits, answer = (M+1)^N.

        long ans = modPow(M + 1L, N, MOD);
        System.out.println(ans);
    }

    static long modPow(long a, long e, long mod) {
        long r = 1 % mod;
        a %= mod;
        while (e > 0) {
            if ((e & 1) != 0) r = (r * a) % mod;
            a = (a * a) % mod;
            e >>= 1;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

from itertools import product
MOD = 10**9 + 7

def solve():
    import sys
    from itertools import product
    input_data = sys.stdin.read().split()
    N, M = int(input_data[0]), int(input_data[1])

    def is_sortable(seq):
        seq = list(seq)
        n = len(seq)
        changed = True
        while changed:
            changed = False
            for i in range(n-1):
                if seq[i] > seq[i+1] and (seq[i] ^ seq[i+1]).bit_count() == 1:
                    seq[i], seq[i+1] = seq[i+1], seq[i]
                    changed = True
        return seq == sorted(seq)

    count = 0
    for seq in product(range(1 << N), repeat=M):
        good = True
        for mask in range(1 << N):
            masked = tuple(x & mask for x in seq)
            if not is_sortable(masked):
                good = False
                break
        if good:
            count += 1
    print(count % MOD)

